# D41 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Python 3.11)
# pip install numpy==2.4.6
# 실행: python d41_flow.py   (모의 부품만 써요 · 인터넷·GPU·Docker·마이크 불필요)
#   부품(WER) → 턴(도구 호출) → 대화(과제 성공·규칙) 세 단계로 v1~v3 비서를 채점하고 내보내도 되는지 문지기 판정
import numpy as np


def check(cond: bool, hint: str = "정답을 다시 확인하세요.") -> None:
    """정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다."""
    print("[정답] 정답입니다!" if cond else f"[다시] {hint}")


def edit_distance(a, b):
    prev = list(range(len(b) + 1))
    for i, x in enumerate(a, 1):
        cur = [i]
        for j, y in enumerate(b, 1):
            cur.append(min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (x != y)))
        prev = cur
    return prev[-1]


def wer(ref, hyp):
    r, h = ref.split(), hyp.split()
    return edit_distance(r, h) / len(r) if r else 0.0

def tool_match(expected, actual):
    """① 개수 같고 ② 순서대로 이름 같고 ③ 기대한 인자가 실제에도 같은 값으로 있으면 True (실제에 인자가 더 있어도 괜찮음)"""
    if len(expected) != len(actual):
        return False
    return all(e["name"] == a["name"] and all(a["args"].get(k) == v for k, v in e["args"].items()) for e, a in zip(expected, actual))


def c(name, /, **args):
    return {"name": name, "args": args}

ORDER = ["treatment", "date", "time", "name", "phone"]
ASK = {"treatment": "어떤 진료를 예약해 드릴까요?", "date": "원하시는 날짜를 말씀해 주세요.", "time": "몇 시가 좋으실까요?",
       "name": "성함을 말씀해 주세요.", "phone": "연락받으실 전화번호를 말씀해 주세요."}
ASK_KEY = {v: k for k, v in ASK.items()}
BUSY = {("모레", "15:00")}                   # 이미 찬 시간 (가상의 예약 장부)
GOALS = {"G1": dict(treatment="스케일링", date="내일", time="10:00", name="김민준", phone="01012345678"),
         "G2": dict(treatment="사랑니 발치", date="다음 주 수요일", time="12:00", name="이서연", phone="01023456789"),
         "G3": dict(treatment="충치 치료", date="모레", time="15:00", alt="16:30", name="박지호", phone="01034567890")}
MAX_TURNS = 10


def book(ver, st):
    s = st["slots"]
    calls = [("check_slot", s["date"], s["time"])]
    if (s["date"], s["time"]) in BUSY and ver == "v3":          # v3만 찬 시간을 알아채고 되묻는다
        del s["time"]
        st["stage"], st["ask"] = "collect", "time"
        return "그 시간은 차 있어요. 다른 시간을 말씀해 주세요.", calls
    st["stage"], st["booking"] = "done", dict(s)
    return "예약되었습니다.", calls + [("book", s["name"], s["time"])]


def hana(ver, st, said):
    """예약 비서 '하나' (모의): v1 확인 없이 예약 · v2 확인 후 예약 · v3 확인 + 찬 시간 되묻기 → (답, 도구 호출들)"""
    if st["stage"] == "confirm":
        return book(ver, st) if said.startswith("네") else (ASK["time"], [])
    st["slots"][st["ask"]] = said
    miss = [k for k in ORDER if k not in st["slots"]]
    if miss:
        st["ask"] = miss[0]
        return ASK[miss[0]], []
    if ver == "v1":
        return book(ver, st)
    st["stage"] = "confirm"
    return '맞으시면 "네"라고 말씀해 주세요.', []


def customer(goal, agent):
    """가상의 환자 (규칙 기반 · 같은 입력이면 같은 답)"""
    if "맞으시면" in agent:
        return "네, 맞아요."
    if "차 있어요" in agent:
        return goal["alt"]
    return goal[ASK_KEY[agent]]


def call_once(ver, goal, hear=lambda text, key: text):
    st = dict(slots={}, stage="collect", ask="treatment", booking=None)
    agent = ASK["treatment"]
    log, calls = [agent], []
    for _ in range(12):
        said = hear(customer(goal, agent), ASK_KEY.get(agent))
        agent, c = hana(ver, st, said)
        log.append(agent)
        calls += c
        if st["stage"] == "done":
            break
    return dict(log=log, calls=calls, booking=st["booking"])


def target(goal):
    t = {k: v for k, v in goal.items() if k != "alt"}
    t["time"] = goal.get("alt", goal["time"])                  # 15시가 차 있으면 16시 30분으로
    return t


def success(goal, booking):
    return booking is not None and all(booking.get(k) == target(goal)[k] for k in ORDER)


def rule_ok(d):
    done = next((i for i, s in enumerate(d["log"]) if "예약되었습니다" in s), None)
    confirmed = done is None or any("맞으시면" in s for s in d["log"][:done])    # 예약보다 앞에 확인하는 말
    return confirmed and len(d["log"]) <= MAX_TURNS


def run_all(ver, hear=lambda text, key: text):
    out = {}
    for gid, goal in GOALS.items():
        d = call_once(ver, goal, hear)
        out[gid] = dict(success=success(goal, d["booking"]), rule=rule_ok(d), log=d["log"], calls=d["calls"])
    return out


# 1단계 부품: 받아쓰기(모의 STT 결과)가 얼마나 틀리나
pairs = [("내일 오전 열 시요", "내일 오전 열 시요"), ("모레 오후 세 시", "모레 오후 네 시")]
parts = float(np.mean([wer(r, h) for r, h in pairs]))
print(f"[부품] 평균 WER {parts:.3f}")

# 2단계 턴: 확인 단계에서 "네" 한 마디 → 도구 호출이 기대와 같은가
st = dict(slots=dict(GOALS["G1"]), stage="confirm", ask="phone", booking=None)
_, calls = hana("v2", st, "네, 맞아요.")
actual = [c("check_slot", date=calls[0][1], time=calls[0][2]), c("book", name=calls[1][1], time=calls[1][2])]
turn_ok = tool_match([c("check_slot", date="내일", time="10:00"), c("book", name="김민준", time="10:00")], actual)
print(f"[턴] 도구 호출 일치: {turn_ok}")

# 3단계 대화: 가상 환자 3명 × 비서 3버전 → 과제 성공률 · 규칙 준수율, 둘 다 100%여야 내보냄(문지기)
gate = {}
for ver in ["v1", "v2", "v3"]:
    res = run_all(ver)
    s, r = np.mean([x["success"] for x in res.values()]), np.mean([x["rule"] for x in res.values()])
    gate[ver] = bool(s == 1.0 and r == 1.0)
    print(f"[대화] {ver}: 과제 성공 {s:.0%} · 규칙 준수 {r:.0%} → {'내보내도 됨' if gate[ver] else '막힘'}")
check(abs(parts - 0.125) < 1e-9 and turn_ok and gate == {"v1": False, "v2": False, "v3": True}, "WER 0.125, 도구 호출 일치, 문지기는 v3만 통과여야 해요.")

flow.typescript:
// D41 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d41_flow.ts
//   부품(WER) → 턴(도구 호출) → 대화(과제 성공·규칙) 세 단계로 v1~v3 비서를 채점하고 내보내도 되는지 문지기 판정
function editDistance(a: string[], b: string[]): number {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    prev = cur;
  }
  return prev[b.length];
}
function wer(ref: string, hyp: string): number {
  const r = ref.split(/\s+/).filter(Boolean), h = hyp.split(/\s+/).filter(Boolean);
  return r.length ? editDistance(r, h) / r.length : 0.0;
}

type ToolCall = { name: string; args: Record<string, string> };
function toolMatch(expected: ToolCall[], actual: ToolCall[]): boolean {
  // ① 개수 같고 ② 순서대로 이름 같고 ③ 기대한 인자가 실제에도 같은 값으로 있으면 true (실제에 인자가 더 있어도 괜찮음)
  if (expected.length !== actual.length) return false;
  return expected.every((e, i) => e.name === actual[i].name && Object.entries(e.args).every(([k, v]) => actual[i].args[k] === v));
}
const c = (name: string, args: Record<string, string> = {}): ToolCall => ({ name, args });

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

type Slots = Record<string, string>;
type Call = string[];
interface State { slots: Slots; stage: string; ask: string; booking: Slots | null }

const ORDER = ["treatment", "date", "time", "name", "phone"];
const ASK: Record<string, string> = { treatment: "어떤 진료를 예약해 드릴까요?", date: "원하시는 날짜를 말씀해 주세요.", time: "몇 시가 좋으실까요?",
  name: "성함을 말씀해 주세요.", phone: "연락받으실 전화번호를 말씀해 주세요." };
const ASK_KEY: Record<string, string> = Object.fromEntries(Object.entries(ASK).map(([k, v]) => [v, k]));
const BUSY = new Set(["모레|15:00"]); // 이미 찬 시간 (가상의 예약 장부)
const GOALS: Record<string, Slots> = {
  G1: { treatment: "스케일링", date: "내일", time: "10:00", name: "김민준", phone: "01012345678" },
  G2: { treatment: "사랑니 발치", date: "다음 주 수요일", time: "12:00", name: "이서연", phone: "01023456789" },
  G3: { treatment: "충치 치료", date: "모레", time: "15:00", alt: "16:30", name: "박지호", phone: "01034567890" },
};
const MAX_TURNS = 10;

function book(ver: string, st: State): [string, Call[]] {
  const s = st.slots;
  const calls: Call[] = [["check_slot", s.date, s.time]];
  if (BUSY.has(`${s.date}|${s.time}`) && ver === "v3") { // v3만 찬 시간을 알아채고 되묻는다
    delete s.time;
    st.stage = "collect"; st.ask = "time";
    return ["그 시간은 차 있어요. 다른 시간을 말씀해 주세요.", calls];
  }
  st.stage = "done"; st.booking = { ...s };
  return ["예약되었습니다.", [...calls, ["book", s.name, s.time]]];
}

function hana(ver: string, st: State, said: string): [string, Call[]] {
  // 예약 비서 '하나' (모의): v1 확인 없이 예약 · v2 확인 후 예약 · v3 확인 + 찬 시간 되묻기
  if (st.stage === "confirm") return said.startsWith("네") ? book(ver, st) : [ASK.time, []];
  st.slots[st.ask] = said;
  const miss = ORDER.filter((k) => !(k in st.slots));
  if (miss.length) { st.ask = miss[0]; return [ASK[miss[0]], []]; }
  if (ver === "v1") return book(ver, st);
  st.stage = "confirm";
  return ['맞으시면 "네"라고 말씀해 주세요.', []];
}

function customer(goal: Slots, agent: string): string {
  // 가상의 환자 (규칙 기반 · 같은 입력이면 같은 답)
  if (agent.includes("맞으시면")) return "네, 맞아요.";
  if (agent.includes("차 있어요")) return goal.alt;
  return goal[ASK_KEY[agent]];
}

interface Talk { log: string[]; calls: Call[]; booking: Slots | null }
type Hear = (t: string, k: string | undefined) => string;
function callOnce(ver: string, goal: Slots, hear: Hear = (t) => t): Talk {
  const st: State = { slots: {}, stage: "collect", ask: "treatment", booking: null };
  let agent = ASK.treatment;
  const log = [agent];
  const calls: Call[] = [];
  for (let i = 0; i < 12; i++) {
    const said = hear(customer(goal, agent), ASK_KEY[agent]);
    const [reply, c] = hana(ver, st, said);
    agent = reply; log.push(agent); calls.push(...c);
    if (st.stage === "done") break;
  }
  return { log, calls, booking: st.booking };
}

function target(goal: Slots): Slots {
  const t: Slots = { ...goal };
  delete t.alt;
  t.time = goal.alt ?? goal.time; // 15시가 차 있으면 16시 30분으로
  return t;
}
const success = (goal: Slots, b: Slots | null): boolean => b !== null && ORDER.every((k) => b[k] === target(goal)[k]);
function ruleOk(d: Talk): boolean {
  const done = d.log.findIndex((s) => s.includes("예약되었습니다"));
  const confirmed = done < 0 || d.log.slice(0, done).some((s) => s.includes("맞으시면")); // 예약보다 앞에 확인하는 말
  return confirmed && d.log.length <= MAX_TURNS;
}

interface Row { success: boolean; rule: boolean; log: string[]; calls: Call[] }
function runAll(ver: string, hear?: Hear): Record<string, Row> {
  const out: Record<string, Row> = {};
  for (const [gid, goal] of Object.entries(GOALS)) {
    const d = callOnce(ver, goal, hear);
    out[gid] = { success: success(goal, d.booking), rule: ruleOk(d), log: d.log, calls: d.calls };
  }
  return out;
}

const parts = ([["내일 오전 열 시요", "내일 오전 열 시요"], ["모레 오후 세 시", "모레 오후 네 시"]] as [string, string][]).map(([r, h]) => wer(r, h));
const mean = (xs: number[]): number => xs.reduce((a, v) => a + v, 0) / xs.length;
console.log(`[부품] 평균 WER ${mean(parts).toFixed(3)}`);

// 2단계 턴: 확인 단계에서 "네" 한 마디 → 도구 호출이 기대와 같은가
const st: State = { slots: { ...GOALS.G1 }, stage: "confirm", ask: "phone", booking: null };
const [, calls] = hana("v2", st, "네, 맞아요.");
const actual = [c("check_slot", { date: calls[0][1], time: calls[0][2] }), c("book", { name: calls[1][1], time: calls[1][2] })];
const turnOk = toolMatch([c("check_slot", { date: "내일", time: "10:00" }), c("book", { name: "김민준", time: "10:00" })], actual);
console.log(`[턴] 도구 호출 일치: ${turnOk}`);

// 3단계 대화: 가상 환자 3명 × 비서 3버전, 둘 다 100%여야 내보냄(문지기)
const gate: Record<string, boolean> = {};
for (const ver of ["v1", "v2", "v3"]) {
  const rows = Object.values(runAll(ver));
  const s = mean(rows.map((x) => (x.success ? 1 : 0))), r = mean(rows.map((x) => (x.rule ? 1 : 0)));
  gate[ver] = s === 1 && r === 1;
  console.log(`[대화] ${ver}: 과제 성공 ${(s * 100).toFixed(0)}% · 규칙 준수 ${(r * 100).toFixed(0)}% → ${gate[ver] ? "내보내도 됨" : "막힘"}`);
}
check(Math.abs(mean(parts) - 0.125) < 1e-9 && turnOk && !gate.v1 && !gate.v2 && gate.v3, "WER 0.125, 도구 호출 일치, 문지기는 v3만 통과여야 해요.");

