}

type Slots = Record<string, string>;
type Call = string[];
interface State { slots: Slots; stage: string; ask: string; booking: Slots | null }

const ORDER = ["treatment", "date", "time", "name", "phone"];
const ASK: Record<string, string> = { treatment: "어떤 진료를 예약해 드릴까요?", date: "원하시는 날짜를 말씀해 주세요.", time: "몇 시가 좋으실까요?",
  name: "성함을 말씀해 주세요.", phone: "연락받으실 전화번호를 말씀해 주세요." };
const ASK_KEY: Record<string, string> = Object.fromEntries(Object.entries(ASK).map(([k, v]) => [v, k]));
const BUSY = new Set(["모레|15:00"]); // 이미 찬 시간 (가상의 예약 장부)
const GOALS: Record<string, Slots> = {
  G1: { treatment: "스케일링", date: "내일", time: "10:00", name: "김민준", phone: "01012345678" },
  G2: { treatment: "사랑니 발치", date: "다음 주 수요일", time: "12:00", name: "이서연", phone: "01023456789" },
  G3: { treatment: "충치 치료", date: "모레", time: "15:00", alt: "16:30", name: "박지호", phone: "01034567890" },
};
const MAX_TURNS = 10;

function book(ver: string, st: State): [string, Call[]] {
  const s = st.slots;
  const calls: Call[] = [["check_slot", s.date, s.time]];
