  // 예약 비서 '하나' (모의): v1 확인 없이 예약 · v2 확인 후 예약 · v3 확인 + 찬 시간 되묻기
  if (st.stage === "confirm") return said.startsWith("네") ? book(ver, st) : [ASK.time, []];
  st.slots[st.ask] = said;
  const miss = ORDER.filter((k) => !(k in st.slots));
  if (miss.length) { st.ask = miss[0]; return [ASK[miss[0]], []]; }
  if (ver === "v1") return book(ver, st);
  st.stage = "confirm";
  return ['맞으시면 "네"라고 말씀해 주세요.', []];
}

function customer(goal: Slots, agent: string): string {
  // 가상의 환자 (규칙 기반 · 같은 입력이면 같은 답)
  if (agent.includes("맞으시면")) return "네, 맞아요.";
  if (agent.includes("차 있어요")) return goal.alt;
  return goal[ASK_KEY[agent]];
}

interface Talk { log: string[]; calls: Call[]; booking: Slots | null }
type Hear = (t: string, k: string | undefined) => string;
function callOnce(ver: string, goal: Slots, hear: Hear = (t) => t): Talk {
  const st: State = { slots: {}, stage: "collect", ask: "treatment", booking: null };
  let agent = ASK.treatment;
  const log = [agent];
  const calls: Call[] = [];
  for (let i = 0; i < 12; i++) {
