ASK_KEY = {v: k for k, v in ASK.items()}
BUSY = {("모레", "15:00")}                   # 이미 찬 시간 (가상의 예약 장부)
GOALS = {"G1": dict(treatment="스케일링", date="내일", time="10:00", name="김민준", phone="01012345678"),
         "G2": dict(treatment="사랑니 발치", date="다음 주 수요일", time="12:00", name="이서연", phone="01023456789"),
         "G3": dict(treatment="충치 치료", date="모레", time="15:00", alt="16:30", name="박지호", phone="01034567890")}
MAX_TURNS = 10


def book(ver, st):
    s = st["slots"]
    calls = [("check_slot", s["date"], s["time"])]
    if (s["date"], s["time"]) in BUSY and ver == "v3":          # v3만 찬 시간을 알아채고 되묻는다
