    agent = ASK["treatment"]
    log, calls = [agent], []
    for _ in range(12):
        said = hear(customer(goal, agent), ASK_KEY.get(agent))
        agent, c = hana(ver, st, said)
        log.append(agent)
        calls += c
        if st["stage"] == "done":
