  t.time = goal.alt ?? goal.time; // 15시가 차 있으면 16시 30분으로
  return t;
}
const success = (goal: Slots, b: Slots | null): boolean => b !== null && ORDER.every((k) => b[k] === target(goal)[k]);
function ruleOk(d: Talk): boolean {
  const done = d.log.findIndex((s) => s.includes("예약되었습니다"));
  const confirmed = done < 0 || d.log.slice(0, done).some((s) => s.includes("맞으시면")); // 예약보다 앞에 확인하는 말
  return confirmed && d.log.length <= MAX_TURNS;
}

interface Row { success: boolean; rule: boolean; log: string[]; calls: Call[] }
function runAll(ver: string, hear?: Hear): Record<string, Row> {
  const out: Record<string, Row> = {};
  for (const [gid, goal] of Object.entries(GOALS)) {
    const d = callOnce(ver, goal, hear);
    out[gid] = { success: success(goal, d.booking), rule: ruleOk(d), log: d.log, calls: d.calls };
  }
  return out;
}

// 모의 STT: 실제 소리 대신 'SNR이 낮을수록 틀리게 들을 확률'만 흉내 낸다 (진짜 Whisper · 합성 잡음은 쓰지 않음)
const SNRS = [40, 20, 10, 0];
const pErr = (snr: number): number => Math.min(1, Math.max(0, (25 - snr) / 25));
let seed = 12345;
const rand = (): number => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }; // 같은 주사위(재현 가능)
const U = Array.from({ length: 15 }, rand); // 시나리오 15개의 주사위: 조건이 달라도 같은 주사위로 비교

const rates: number[] = [];
for (const snr of SNRS) {
  let ok = 0;
  for (let i = 0; i < 15; i++) {
    const goal = GOALS[`G${(i % 3) + 1}`];
    const hear: Hear = (text, key) => (key === "phone" && U[i] < pErr(snr) ? text.slice(0, -1) + (text.endsWith("0") ? "1" : "0") : text);
    ok += success(goal, callOnce("v3", goal, hear).booking) ? 1 : 0;
  }
  rates.push(ok / 15);
  console.log(`SNR ${snr} dB | 틀리게 들을 확률 ${(pErr(snr) * 100).toFixed(0)}% | 과제 성공률 ${(rates[rates.length - 1] * 100).toFixed(0)}%`);
}
check(rates[0] === 1 && rates[rates.length - 1] === 0 && rates.every((r, i) => i === 0 || rates[i - 1] >= r), "깨끗하면 100%, 잡음이 커질수록 성공률이 줄기만 해야 해요.");

