// D41 · Part 5 · 정리 퀴즈 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d41_recap.ts
//   WER · 도구 호출 일치 · 과제 성공 · 회귀 찾기 네 가지 핵심 함수를 한 번에 자기 확인
function editDistance(a: string[], b: string[]): number {
  let prev = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    const cur = [i];
    for (let j = 1; j <= b.length; j++) cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] !== b[j - 1] ? 1 : 0)));
    prev = cur;
  }
  return prev[b.length];
}
function wer(ref: string, hyp: string): number {
  const r = ref.split(/\s+/).filter(Boolean), h = hyp.split(/\s+/).filter(Boolean);
  return r.length ? editDistance(r, h) / r.length : 0.0;
}

type ToolCall = { name: string; args: Record<string, string> };
function toolMatch(expected: ToolCall[], actual: ToolCall[]): boolean {
  // ① 개수 같고 ② 순서대로 이름 같고 ③ 기대한 인자가 실제에도 같은 값으로 있으면 true (실제에 인자가 더 있어도 괜찮음)
  if (expected.length !== actual.length) return false;
  return expected.every((e, i) => e.name === actual[i].name && Object.entries(e.args).every(([k, v]) => actual[i].args[k] === v));
}
const c = (name: string, args: Record<string, string> = {}): ToolCall => ({ name, args });

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function taskSuccess(goal: Record<string, string>, booking: Record<string, string> | null): boolean {
  // booking이 null이면 false, 다섯 칸이 모두 같을 때만 true
  return booking !== null && ["treatment", "date", "time", "name", "phone"].every((k) => booking[k] === goal[k]);
}
const regressions = (base: Record<string, boolean>, next: Record<string, boolean>): string[] =>
  Object.entries(base).filter(([k, v]) => v && next[k] !== true).map(([k]) => k).sort();

const g = { treatment: "스케일링", date: "내일", time: "10:00", name: "김민준", phone: "01012345678" };
console.log("1. WER(정답 4낱말, 1개 틀림) =", wer("내일 오후 세 시요", "내일 오후 네 시요"));
check(wer("내일 오후 세 시요", "내일 오후 네 시요") === 0.25 && wer("", "네") === 0, "1개 틀린 4낱말은 0.25, 정답이 비면 0.0 이에요.");
check(toolMatch([c("book", { time: "15:00" })], [c("book", { time: "15:00", name: "김민준" })]) && !toolMatch([c("book")], []), "인자가 더 있는 건 괜찮고, 호출 개수는 같아야 해요.");
check(taskSuccess(g, { ...g }) && !taskSuccess(g, null) && !taskSuccess(g, { ...g, time: "09:00" }), "예약이 없거나 한 칸이라도 다르면 실패예요.");
check(JSON.stringify(regressions({ a: true, b: true }, { a: true })) === '["b"]', "없어진 시나리오도 회귀로 세요.");
